class WordBook {
  constructor() {
    this.root = { next: new Map(), end: false }
  }

  add(word) {
    let node = this.root
    for (const ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, { next: new Map(), end: false })
      node = node.next.get(ch)
    }
    node.end = true
  }

  find(pattern) {
    const stack = [[this.root, 0]]
    while (stack.length) {
      const [node, i] = stack.pop()
      if (i === pattern.length) {
        if (node.end) return true
        continue
      }
      const ch = pattern[i]
      if (ch === '.') {
        for (const child of node.next.values()) stack.push([child, i + 1])
      } else if (node.next.has(ch)) {
        stack.push([node.next.get(ch), i + 1])
      }
    }
    return false
  }
}

function runWordBook(ops) {
  const book = new WordBook()
  return ops.map(([op, text]) => (op === 'add' ? (book.add(text), null) : book.find(text)))
}

